import numpy as np
import pandas as pd

train = pd.read_csv('train.csv')
feature_columns = [c for c in train.columns if c not in {'entity_id', 'target'}]
X_raw = train[feature_columns].to_numpy(float)
y = train['target'].to_numpy(float)
cor = train[feature_columns + ['target']].corr(numeric_only=True)['target'].drop('target').abs().sort_values(ascending=False)
top = list(cor.head(8).index)
top_idx = [feature_columns.index(c) for c in top]

alphas = [0.0, 1e-3, 1e-2, 1e-1, 1.0, 10.0, 100.0]
fold_ids = np.arange(len(X_raw)) % 5


def standardize(xtr, xva):
    mean = xtr.mean(axis=0)
    std = xtr.std(axis=0)
    std[std == 0.0] = 1.0
    return (xtr - mean) / std, (xva - mean) / std


def fit_ridge(x, y, alpha):
    design = np.hstack([np.ones((len(x), 1)), x])
    reg = np.eye(design.shape[1]) * alpha
    reg[0, 0] = 0.0
    return np.linalg.solve(design.T @ design + reg, design.T @ y)


def predict(x, w):
    return w[0] + x @ w[1:]


def rmse(a, b):
    return float(np.sqrt(np.mean((a - b) ** 2)))


def make_features(name, x):
    if name == 'linear':
        return x
    if name == 'quadratic':
        return np.hstack([x, x ** 2])
    if name == 'top_interactions':
        cols = [x]
        top_x = x[:, top_idx]
        cols.append(top_x ** 2)
        pair_terms = []
        for i in range(top_x.shape[1]):
            for j in range(i + 1, top_x.shape[1]):
                pair_terms.append((top_x[:, i] * top_x[:, j])[:, None])
        cols.extend(pair_terms)
        return np.hstack(cols)
    if name == 'quadratic_plus_top_interactions':
        cols = [x, x ** 2]
        top_x = x[:, top_idx]
        for i in range(top_x.shape[1]):
            for j in range(i + 1, top_x.shape[1]):
                cols.append((top_x[:, i] * top_x[:, j])[:, None])
        return np.hstack(cols)
    raise ValueError(name)

for name in ['linear', 'quadratic', 'top_interactions', 'quadratic_plus_top_interactions']:
    best = None
    for alpha in alphas:
        scores = []
        for fold in range(5):
            tr = fold_ids != fold
            va = ~tr
            xtr, xva = standardize(X_raw[tr], X_raw[va])
            xtr = make_features(name, xtr)
            xva = make_features(name, xva)
            w = fit_ridge(xtr, y[tr], alpha)
            scores.append(rmse(y[va], predict(xva, w)))
        score = float(np.mean(scores))
        if best is None or score < best[1]:
            best = (alpha, score)
    print(name, best)
print('top_features', top)
